'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef, useId } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface Folder01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface Folder01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// A sheet drops into the folder from above and slips behind the front edge;
// the folder takes its weight with a short squash and rebound.
const DROP_DURATION = 1.1;

const folderVariants: Variants = {
  normal: { scaleX: 1, scaleY: 1 },
  animate: {
    scaleX: [1, 1, 1.05, 0.98, 1.005, 1],
    scaleY: [1, 1, 0.87, 1.04, 0.99, 1],
    transition: {
      duration: DROP_DURATION,
      ease: 'easeInOut',
      times: [0, 0.5, 0.62, 0.76, 0.88, 1],
    },
  },
};

const sheetVariants: Variants = {
  normal: { translateY: -7.5 },
  animate: {
    translateY: [-7.5, 7, 7],
    transition: {
      duration: DROP_DURATION,
      ease: [[0.55, 0, 0.9, 0.5], 'linear'],
      times: [0, 0.56, 1],
    },
  },
};

const generatedGeometryVariants: Variants = {
  normal: { visibility: 'hidden', transition: { duration: 0 } },
  animate: {
    visibility: ['visible', 'visible', 'hidden'],
    transition: { duration: DROP_DURATION, times: [0, 0.58, 0.59] },
  },
};

const Folder01Icon = forwardRef<Folder01IconHandle, Folder01IconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const clipId = useId();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <defs>
            <clipPath id={clipId} clipPathUnits="userSpaceOnUse">
              <rect x="12.8" y="-0.5" width="8.6" height="6.2" />
            </clipPath>
          </defs>
          <motion.g
            variants={generatedGeometryVariants}
            animate={controls}
            initial="normal"
            clipPath={`url(#${clipId})`}
          >
            <motion.rect
              x="14.25"
              y="0.35"
              width="5.5"
              height="5.6"
              rx="1.2"
              stroke="currentColor"
              strokeWidth="1.5"
              variants={sheetVariants}
              animate={controls}
              initial="normal"
            />
          </motion.g>
          <motion.path
            d="M8 7H16.75C18.8567 7 19.91 7 20.6667 7.50559C20.9943 7.72447 21.2755 8.00572 21.4944 8.33329C22 9.08996 22 10.1433 22 12.25C22 15.7612 22 17.5167 21.1573 18.7779C20.7926 19.3238 20.3238 19.7926 19.7779 20.1573C18.5167 21 16.7612 21 13.25 21H12C7.28595 21 4.92893 21 3.46447 19.5355C2 18.0711 2 15.714 2 11V7.94427C2 6.1278 2 5.21956 2.38032 4.53806C2.65142 4.05227 3.05227 3.65142 3.53806 3.38032C4.21956 3 5.1278 3 6.94427 3C8.10802 3 8.6899 3 9.19926 3.19101C10.3622 3.62712 10.8418 4.68358 11.3666 5.73313L12 7"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={folderVariants}
            animate={controls}
            initial="normal"
            style={{ transformBox: 'view-box', originX: 12 / 24, originY: 21 / 24 }}
          />
        </svg>
      </div>
    );
  }
);

Folder01Icon.displayName = 'Folder01Icon';

export { Folder01Icon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { spring, useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

/**
 * A damped spring as the easing of one keyframe segment: the value overshoots
 * its target and settles on it. Use it for landings so every icon shares the
 * same physical bounce. Higher `bounce` gives more oscillation.
 */
export function springEase(bounce = 0.45, visualDuration = 0.35) {
  const generator = spring({ keyframes: [0, 1], bounce, visualDuration });
  let settle = 0;
  while (!generator.next(settle).done && settle < 5000) settle += 10;
  return (progress: number) =>
    progress >= 1 ? 1 : generator.next(progress * settle).value;
}

const NUMBER = /-?\d*\.?\d+/g;

/**
 * The path at position `t` along a row of poses that share the same path
 * commands: `t = 1` is the second pose, `t = 1.5` is halfway to the third.
 * Waves use it to move along their own curvature instead of scaling, so the
 * stroke keeps its width.
 */
export function pathAt(poses: string[], t: number) {
  const i = Math.min(Math.max(Math.floor(t), 0), poses.length - 2);
  const to = poses[i + 1].match(NUMBER) ?? [];
  let k = 0;
  return poses[i].replace(NUMBER, (from) => {
    const value = Number(from) + (Number(to[k++]) - Number(from)) * (t - i);
    return String(Math.round(value * 10000) / 10000);
  });
}

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
